[InitializeOnLoad]public static class BattleRefreshAuthoring
{
 public const string Out="output/battle-refresh/",Root="Assets/DarkFairytale/UI/BattleRefresh/";
 static Font font;static Texture2D art,blank;static Sprite meterArt,headerArt;
 static BattleRefreshAuthoring(){EditorApplication.update+=()=>{if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists(Out+"build.request"))return;File.Delete(Out+"build.request");try{Build();File.WriteAllText(Out+"build.txt","PASS");}catch(Exception e){File.WriteAllText(Out+"build.txt",e.ToString());}};}
 static Texture2D Import(string n){string p=ArtSourcePaths.Resolve(Root+"Art/"+n+".png");var i=(TextureImporter)AssetImporter.GetAtPath(p);i.textureType=TextureImporterType.Default;i.mipmapEnabled=false;i.isReadable=true;i.alphaIsTransparency=true;i.maxTextureSize=2048;i.textureCompression=TextureImporterCompression.Uncompressed;i.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(p);}
 static Sprite Trimmed(string name,Vector4 border){var tex=Import(name);string path=Root+"Sprites/"+name+"Transparent.asset";var old=AssetDatabase.LoadAssetAtPath<Sprite>(path);if(old)return old;var pixels=tex.GetPixels32();int left=tex.width,right=0,bottom=tex.height,top=0;for(int y=0;y<tex.height;y++)for(int x=0;x<tex.width;x++)if(pixels[y*tex.width+x].a>25){left=Math.Min(left,x);right=Math.Max(right,x);bottom=Math.Min(bottom,y);top=Math.Max(top,y);}var s=ProductionUiArt.Create(tex,new Rect(left,bottom,right-left+1,top-bottom+1),Vector2.one*.5f,100,0,SpriteMeshType.FullRect,border);AssetDatabase.CreateAsset(s,path);return s;}
 static Sprite Slice(string n,Texture2D tex,int x,int y,int w,int h,Vector4 border=default){string p=Root+"Sprites/"+n+".asset";var s=AssetDatabase.LoadAssetAtPath<Sprite>(p);if(s)return s;s=ProductionUiArt.Create(tex,new Rect(x,tex.height-y-h,w,h),Vector2.one*.5f,100,0,SpriteMeshType.FullRect,border);AssetDatabase.CreateAsset(s,p);return s;}
 static RectTransform Node(Transform p,string n,float x,float y,float w,float h){var g=new GameObject(n,typeof(RectTransform));g.layer=5;g.transform.SetParent(p,false);var r=(RectTransform)g.transform;StorybookEquipmentLayout.Box(r,x,y,w,h);return r;}
 static Image Pic(Transform p,string n,Sprite s,float x,float y,float w,float h){var r=Node(p,n,x,y,w,h);var im=r.gameObject.AddComponent<Image>();im.sprite=s;im.raycastTarget=false;return im;}
 static Text Txt(Transform p,string n,string v,float x,float y,float w,float h,int size,TextAnchor align=TextAnchor.MiddleLeft){var r=Node(p,n,x,y,w,h);var t=r.gameObject.AddComponent<Text>();t.font=font;t.text=v;t.fontSize=size;t.color=new Color(.075f,.055f,.04f);t.alignment=align;t.raycastTarget=false;t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Overflow;return t;}
 static Image Meter(Transform p,string n,float x,float y,float w,float h,Color color){var bg=Pic(p,n+"Track",null,x+9,y+6,w-18,h-12);bg.color=new Color(.06f,.065f,.065f);var im=Pic(p,n+"Fill",AssetDatabase.LoadAssetAtPath<Sprite>(CursedStorybookUiBuilder.Root+"/Sprites/"+(n=="Experience"?"ExperienceInk":"HealthInk")+".asset"),x+9,y+6,w-18,h-12);im.color=color;im.type=Image.Type.Filled;im.fillMethod=Image.FillMethod.Horizontal;var frame=Pic(p,n+"Frame",meterArt,x,y,w,h);frame.type=Image.Type.Sliced;frame.pixelsPerUnitMultiplier=h<30?5:3;frame.fillCenter=false;return im;}
 public static void Build(){font=AssetDatabase.LoadAssetAtPath<Font>(CursedStorybookUiBuilder.Root+"/Fonts/NotoSerifCJKsc-Black.otf");art=Import("ApprovedLayout");blank=Import("BlankLayout");meterArt=Trimmed("Meter",new Vector4(65,32,65,32));headerArt=Trimmed("Header",Vector4.zero);var root=PrefabUtility.LoadPrefabContents(CursedStorybookUiBuilder.HudPath);
 try{var ui=root.GetComponent<CursedBattleHud>();var safe=root.GetComponent<BattleHudSafeArea>();var core=safe.core;foreach(Transform child in core.Cast<Transform>().ToArray())UnityEngine.Object.DestroyImmediate(child.gameObject);safe.referenceSize=new Vector2(941,1672);safe.bottomInset=30;
 var head=Pic(core,"ChapterHeader",headerArt,45,48,850,165);ui.waveText=Txt(head.transform,"WaveText","第 1 / 3 波",240,12,380,55,37,TextAnchor.MiddleCenter);
 var back=Pic(head.transform,"Return",null,24,0,85,140);back.color=Color.white;back.raycastTarget=true;ui.backButton=back.gameObject.AddComponent<Button>();ui.backButton.targetGraphic=back;var colors=ui.backButton.colors;colors.pressedColor=new Color(0,0,0,.25f);colors.normalColor=Color.clear;colors.highlightedColor=Color.clear;ui.backButton.colors=colors;
 var progress=Node(head.transform,"Progress",350,85,150,24);ui.progressRow=progress.gameObject;var hl=progress.gameObject.AddComponent<HorizontalLayoutGroup>();hl.spacing=12;hl.childAlignment=TextAnchor.MiddleCenter;hl.childControlHeight=hl.childControlWidth=false;hl.childForceExpandHeight=hl.childForceExpandWidth=false;ui.waveMarkers=new Image[8];
 for(int i=0;i<8;i++){var box=Node(progress,"Wave"+i,0,0,20,20);var edge=Pic(box,"Outline",null,2,2,16,16);edge.color=new Color(.1f,.07f,.04f);edge.transform.localEulerAngles=new Vector3(0,0,45);var dot=Pic(edge.transform,"State",null,3,3,10,10);ui.waveMarkers[i]=dot;}
 var panel=Pic(core,"PlayerStatus",Slice("Panel",blank,17,1330,909,304),0,0,909,304);panel.rectTransform.anchorMin=panel.rectTransform.anchorMax=panel.rectTransform.pivot=new Vector2(.5f,0);panel.rectTransform.anchoredPosition=new Vector2(0,30);safe.bottomPanel=panel.rectTransform;
 Pic(panel.transform,"Portrait",Slice("Portrait",art,74,1362,176,183),57,32,176,183);
 var levelPaper=Pic(panel.transform,"LevelPaper",null,57,215,176,42);levelPaper.color=Color.clear;ui.levelText=Txt(levelPaper.transform,"Level","Lv. 1",0,0,176,42,29,TextAnchor.MiddleCenter);
 Txt(panel.transform,"HealthLabel","生命",270,23,100,43,29);ui.hpText=Txt(panel.transform,"HP","12 / 14",390,15,450,52,46,TextAnchor.MiddleRight);ui.hpText.color=new Color(.49f,.045f,.025f);ui.hpFill=Meter(panel.transform,"Health",263,67,595,43,Color.white);
 Txt(panel.transform,"ExperienceLabel","经验",270,111,100,30,23);ui.xpText=Txt(panel.transform,"XP","0%",650,111,190,30,23,TextAnchor.MiddleRight);ui.xpFill=Meter(panel.transform,"Experience",263,140,595,24,new Color(.32f,.46f,.58f));
 var status=root.GetComponent<BattleStatusDetails>();if(!status)status=root.AddComponent<BattleStatusDetails>();ui.statusDetails=status;
 var skills=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/DarkFairytale/UI/Skills/StorybookSkills.prefab");if(!skills)skills=AssetDatabase.LoadAssetAtPath<GameObject>(StorybookSkillsBuilder.Path);
 var source=skills.GetComponent<StorybookSkillsUI>();status.keys=new[]{SkillsTypeEnum.Regen,SkillsTypeEnum.Angel_On_My_Shoulder,SkillsTypeEnum.Devil_On_My_Shoulder,SkillsTypeEnum.Lightning_Demi_God,SkillsTypeEnum.PetCindrel};status.skillSlots=new GameObject[5];status.cooldownMasks=new Image[5];
 var row=Node(panel.transform,"SkillStatus",270,177,570,76);var layout=row.gameObject.AddComponent<HorizontalLayoutGroup>();layout.spacing=24;layout.childControlHeight=layout.childControlWidth=false;layout.childForceExpandWidth=layout.childForceExpandHeight=false;layout.childAlignment=TextAnchor.MiddleLeft;
 for(int i=0;i<5;i++){var n=source.nodes.First(n=>n.key==status.keys[i]);var icon=Pic(row,status.keys[i].ToString(),n.icon.sprite,0,0,76,76);icon.preserveAspect=true;icon.material=n.icon.material;status.skillSlots[i]=icon.gameObject;var mask=Pic(icon.transform,"ClockwiseCooldown",n.icon.sprite,0,0,76,76);var mp=Root+"Sprites/Cooldown"+i+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(mp);if(!mat){mat=new Material(Shader.Find("UI/Storybook Disabled"));mat.SetFloat("_DisabledUI",1);AssetDatabase.CreateAsset(mat,mp);}mask.material=mat;mask.preserveAspect=true;mask.color=new Color(.4f,.4f,.4f,.9f);mask.type=Image.Type.Filled;mask.fillMethod=Image.FillMethod.Radial360;mask.fillOrigin=(int)Image.Origin360.Top;mask.fillClockwise=false;mask.fillAmount=0;status.cooldownMasks[i]=mask;}
 status.notificationAnchor=Node(panel.transform,"PortraitFloatOrigin",24,-55,260,70);status.notification=Node(panel.transform,"PortraitFloat",24,-55,280,80);status.notificationText=Txt(status.notification,"Text","经验 +25",0,0,280,80,27,TextAnchor.MiddleCenter);status.notificationText.color=new Color(1,.84f,.46f);var outline=status.notificationText.gameObject.AddComponent<Outline>();outline.effectColor=new Color(.09f,.04f,.02f,.95f);outline.effectDistance=new Vector2(1.5f,-1.5f);status.notificationGroup=status.notification.gameObject.AddComponent<CanvasGroup>();status.notificationGroup.alpha=0;status.notificationGroup.blocksRaycasts=status.notificationGroup.interactable=false;
 ui.SetWave(1,3);safe.Apply();ProductionUiArt.SaveAsPrefabAsset(root,CursedStorybookUiBuilder.HudPath);
 }finally{PrefabUtility.UnloadPrefabContents(root);}
 BattleFeedbackAuthoring.Build();
 var enemy=PrefabUtility.LoadPrefabContents(CursedStorybookUiBuilder.EnemyPath);try{var bar=enemy.GetComponent<EnemyLifebar>();var frame=enemy.transform.Find("HealthFrame").GetComponent<Image>();frame.sprite=meterArt;frame.type=Image.Type.Sliced;frame.pixelsPerUnitMultiplier=3;frame.fillCenter=false;frame.rectTransform.sizeDelta=new Vector2(360,48);var fill=bar.hpMeter.GetComponent<Image>();fill.rectTransform.sizeDelta=new Vector2(338,32);var bg=Pic(enemy.transform,"EmptyTrack",null,0,0,338,32);bg.rectTransform.anchorMin=bg.rectTransform.anchorMax=Vector2.one*.5f;bg.rectTransform.pivot=Vector2.one*.5f;bg.rectTransform.anchoredPosition=Vector2.zero;bg.color=new Color(.055f,.06f,.06f);bg.transform.SetAsFirstSibling();bar.hpText.rectTransform.anchoredPosition=Vector2.zero;bar.hpText.font=font;bar.hpText.fontSize=34;bar.hpText.resizeTextForBestFit=false;bar.hpText.transform.SetAsLastSibling();ProductionUiArt.SaveAsPrefabAsset(enemy,CursedStorybookUiBuilder.EnemyPath);}finally{PrefabUtility.UnloadPrefabContents(enemy);}AssetDatabase.SaveAssets();
 }
}
